draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw a stick figure character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 80);
  ctx.stroke();

  // Draw a fruit (apple) 
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.sin(t), H/2 - 20, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.stroke();

  // Draw a speech bubble with a carrot
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2 - 50 + 10*Math.cos(t), H/2 - 80, 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + 10*Math.cos(t), H/2 - 50);
  ctx.lineTo(W/2 - 50 + 10*Math.cos(t), H/2 - 30);
  ctx.stroke();
  ctx.fillStyle = 'orange';
  ctx.beginPath();
  ctx.arc(W/2 - 50 + 10*Math.cos(t), H/2 - 40, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.stroke();

  ctx.restore();
}
